import math

class GFG :
    @staticmethod
    def  largest( arr,  n,  i) :

        # last index
        # return the element
        if (i == n - 1) :
            return arr[i]

        # find the maximum from rest of the array
        recMax = GFG.largest(arr, n, i + 1)

        # compare with i-th element and return
        return max(recMax,arr[i])

