def findFirstMissing(array, start, end):

    if (start > end):
        return end + 1

    if (start != array[start]):
        return start;

    mid = int((start + end) / 2)

    # Left half has all elements
    # from 0 to mid
    if (array[mid] == mid):
        return findFirstMissing(array,
                          mid+1, end)

    return findFirstMissing(array,
                          start, mid)


