def binarySearch(arr, low, high, key):

    mid = (low + high)/2

    if (key == arr[int(mid)]):
        return mid

    if (key > arr[int(mid)]):
        return binarySearch(arr,
                            (mid + 1), high, key)

    if (key < arr[int(mid)]):
        return binarySearch(arr, low, (mid-1), key)

    return 0


