# Function to build tree using given traversal
def buildTree(preorder, inorder, n):
    root = None;

    pre = 0
    in_t = 0

    while pre < n:
        node = None;

        while True:   
            node = TreeNode(preorder[pre])

            if (root == None):           
                root = node;

            if (len(st) > 0):       
                if (st[-1] in s):               
                    s.discard(st[-1]);
                    st[-1].right = node;
                    st.pop();

                else:               
                    st[-1].left = node;

            st.append(node);

            if pre>=n or preorder[pre] == inorder[in_t]:
                pre += 1
                break
            pre += 1

        node = None;

        while (len(st) > 0 and in_t < n and st[-1].val == inorder[in_t]):       
            node = st[-1];
            st.pop();
            in_t += 1


        if (node != None):       
            s.add(node);
            st.append(node);

    return root;

