''' A linked list Node '''
class Node:
    def __init__(self, data):
        self.data = data;
        self.next = None;

''' Function to add new Node to the List '''
def append(headRef,  data):
    new_Node =  Node(data);
    last = headRef;
    if (headRef == None):
        headRef = new_Node;
        return headRef;

    while (last.next != None):
        last = last.next;
    last.next = new_Node;
    return headRef;

# utility function to print linked list
def printlist(head):
    if (head == None):
        print("Empty List");
        return;

    while (head != None):
        print(head.data, end="");
        if (head.next != None):
            print("-> ",end="");
        head = head.next;

    print();


'''
 * function to arrange consonants and vowels Nodes
 '''
def arrange(head):
    vowel = None;
    consonant = None;
    start = None;
    end = None;
    while (head != None):
        x = head.data;

        # Checking the current Node data is vowel or
        # not
        if (x == 'a' or x == 'e' or x == 'i' or x == 'o' or x == 'u'):
            if (vowel == None):
                vowel =  Node(x);
                start = vowel;
            else:
                vowel.next =  Node(x);
                vowel = vowel.next;

        else:
            if (consonant == None):
                consonant =  Node(x);
                end = consonant;
            else:
                consonant.next =  Node(x);
                consonant = consonant.next;


        head = head.next;

    # In case when there is no vowel in the incoming LL
    # then we have to return the head of the consonant LL
    if (start == None):
        return end;

    # Connecting the vowel and consonant LL
    vowel.next = end;
    return start;

