# Python implementation to
# count sub-matrices having
# sum divisible by the
# value 'k'

# function to count all
# sub-arrays divisible by k
def subCount(arr, n, k) :

    # create auxiliary hash
    # array to count frequency
    # of remainders
    mod = [0] * k;

    # Traverse original array
    # and compute cumulative
    # sum take remainder of
    # this current cumulative
    # sum and increase count
    # by 1 for this remainder
    # in mod array
    cumSum = 0;
    for i in range(0, n) :

        cumSum = cumSum + arr[i];

        # as the sum can be
        # negative, taking
        # modulo twice
        mod[((cumSum % k) + k) % k] = mod[
                   ((cumSum % k) + k) % k] + 1;

    result = 0; # Initialize result

    # Traverse mod
    for i in range(0, k) :

        # If there are more than
        # one prefix subarrays
        # with a particular mod value.
        if (mod[i] > 1) :
            result = result + int((mod[i] *
                     (mod[i] - 1)) / 2);

    # add the subarrays starting
    # from the arr[i] which are
    # divisible by k itself
    result = result + mod[0];

    return result;

# function to count all
# sub-matrices having sum
# divisible by the value 'k'
def countSubmatrix(mat, n, k) :

    # Variable to store
    # the final output
    tot_count = 0;

    temp = [0] * n;

    # Set the left column
    for left in range(0, n - 1) :

        # Set the right column
        # for the left column
        # set by outer loop
        for right in range(left, n) :    

            # Calculate sum between
            # current left and right
            # for every row 'i'
            for i in range(0, n) :
                temp[i] = (temp[i] +
                           mat[i][right]);

            # Count number of subarrays
            # in temp having sum
            # divisible by 'k' and then
            # add it to 'tot_count'
            tot_count = (tot_count +
                         subCount(temp, n, k));

    # required count of
    # sub-matrices having
    # sum divisible by 'k'
    return tot_count;

