    # Function call to push number's
    # digits to stack
    push_digits(number);

    reverse = 0;
    i = 1;

    # Popping the digits and forming
    # the reversed number
    while (len(st) > 0):
        reverse = reverse + (st[len(st) - 1] * i);
        st.pop();
        i = i * 10;

