# A function to check if n is palindrome
def isPalindrome(n: int) -> bool:

    # Find reverse of n
    rev = 0
    i = n
    while i > 0:
        rev = rev * 10 + i % 10
        i //= 10

    # If n and rev are same, 
    # then n is palindrome
    return (n == rev)

