# function to calculate the minimal changes
def calculate( s):

    # maximum digits that can be changed
    ans = 6

    # nested loops to generate all 6
    # digit numbers
    for i in range(10):
        for j in range(10):
            for k in range(10):
                for l in range(10):
                    for  m in range(10):
                        for n in range(10):
                            if (i + j + k == l + m + n):

                                # counter to count the number
                                # of change required
                                c = 0

                                # if first digit is equal
                                if (i != ord(s[0]) - ord('0')):
                                    c+=1

                                # if 2nd digit is equal   
                                if (j != ord(s[1]) - ord('0')):
                                    c+=1

                                # if 3rd digit is equal   
                                if (k != ord(s[2]) - ord('0')):
                                    c+=1

                                # if 4th digit is equal   
                                if (l != ord(s[3]) - ord('0')):
                                    c+=1

                                # if 5th digit is equal   
                                if (m != ord(s[4]) - ord('0')):
                                    c+=1

                                # if 6th digit is equal   
                                if (n != ord(s[5]) - ord('0')):
                                    c+=1

                                # checks if less than the
                                # previous calculate changes
                                if (c < ans):
                                    ans = c

    # returns the answer
    return ans

